 c=rgb/255.;c=np.where(c<=.04045,c/12.92,((c+.055)/1.055)**2.4);xyz=c@np.array([[.4124564,.3575761,.1804375],[.2126729,.7151522,.072175],[.0193339,.119192,.9503041]]).T;xyz/=np.array([.95047,1,1.08883]);d=6/29;f=np.where(xyz>d**3,xyz**(1/3),xyz/(3*d*d)+4/29);return np.stack((116*f[...,1]-16,500*(f[...,0]-f[...,1]),200*(f[...,1]-f[...,2])),-1)
hexes=['dfbd62','c39a47','9b9e66','858b58','9a7738','666846','855c2d','4e523e','6d482a','543b3a','593828','40352b','342834','3c2322','2c1d23','1e1625'];P=lab(np.array([list(bytes.fromhex(h)) for h in hexes],np.float32));T=lab(im);N=76;labels=np.zeros((N,N),np.uint8)
for r in range(N):
 for c in range(N):
  avg=T[r*1024//N:(r+1)*1024//N,c*1024//N:(c+1)*1024//N].mean((0,1));labels[r,c]=np.argmin(((P-avg)**2).sum(1))
colors=np.array([list(bytes.fromhex(x)) for x in hexes],np.uint8)
Image.fromarray(colors[labels].repeat(8,0).repeat(8,1)).save('/app/output/quantized76.png')
